const initialState=()=>({page:'cases',theme:'dark',sidebar:true,files:true,panel:'files',caseMode:'map',projectMode:'cards',detailCase:null,detailProject:null,task:'t1',project:'p1',settingsTab:'model',studioTab:'foundation',professional:null,caseTab:'work',query:'',notice:'',reportVersion:1,reviewTab:'review',reviews:{1:{reviewed:true,carried:false},2:{reviewed:false,carried:false}},auto:{save:false,review:false,ir:false,case:false,assets:false},goal:{id:'G-01',version:1,title:'会员持续购买',metric:'SAP 适用会员复购率 v3',baseline:'待补可比历史窗口'},caseGoalRefs:{c1:{id:'G-01',version:1,title:'会员持续购买'},c2:{id:'G-02',version:1,title:'经营贡献'}},goalHistory:[],goalCandidate:false,goalLevel:'enterprise',method:{id:'M-03',version:3,status:'published',candidate:null,error:false},choice:null,feedback:null,operations:{},confirmed:null,plan:{mode:'multi',selected:['t1','t2'],singleTask:'t1',summary:'t3',noCase:false,skills:{analysis:true,research:true,ir:true},limited:true},projects:[{id:'p1',name:'会员复购改善',owner:'会员运营',scope:'核对复购变化的范围与依据，比较有证据的改善方向。',next:'确认本轮需求与重点，继续已有综合任务。',archived:false},{id:'p2',name:'商品供给研究',owner:'商品团队',scope:'沿获准资料核对关键款供给与服务线索。',next:'保留本轮材料，按实际发现反馈。',archived:false}],tasks:[{id:'t1',project:'p1',name:'会员群体与购买变化',created:true,status:'idle',archived:false,draft:''},{id:'t2',project:'p1',name:'商品、服务与外部证据',created:false,status:'idle',archived:false,draft:''},{id:'t3',project:'p1',name:'项目综合与方案比较',created:true,status:'idle',archived:false,draft:''},{id:'t4',project:'p2',name:'关键款可得性核对',created:true,status:'idle',archived:false,draft:''}],expanded:['p1','p2'],showArchived:false});
let D=initialState();
const H=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='secondary-button',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const badge=x=>`<span class="v020-badge">${H(x)}</span>`;
const section=(title,body,extra='')=>`<section class="v020-section ${extra}"><h2>${title}</h2>${body}</section>`;
const table=(headers,rows)=>`<div class="v020-table"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const heading=(title,desc,action='')=>`<header class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${action}</header>`;
const check=(id,label,checked,change,disabled=false)=>`<label class="v020-check"><input id="${id}" type="checkbox" data-change="${change}" ${checked?'checked':''} ${disabled?'disabled':''}> <span>${label}</span></label>`;
const input=(id,label,value='',attrs='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" value="${H(value)}" ${attrs}></div>`;
const icon=(name)=>{const paths={plus:'<path d="M12 5v14M5 12h14"/>',folder:'<path d="M3 7V5a2 2 0 012-2h5l2 3h7a2 2 0 012 2v11a2 2 0 01-2 2H5a2 2 0 01-2-2V7Z"/>',panel:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16"/>',assets:'<path d="m3 7 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5M3 17l9 5 9-5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3 1-1h4l1 3 3 1 3 3-1 3 1 3-3 3-3 1-1 3h-4l-1-3-3-1-3-3 1-3-1-3 3-3 3-1Z"/>',goal:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 016 0c0 2-3 2-3 4m0 3v1"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.panel}</svg>`;};
const activeProject=()=>D.projects.find(x=>x.id===D.project)||D.projects[0];
const activeTask=()=>D.tasks.find(x=>x.id===D.task&&x.project===D.project)||{id:'',project:D.project,name:'尚未创建任务',status:'idle',draft:''};
const taskStatus=t=>t.archived?'已归档':({idle:'空闲',running:'运行中',stopped:'已停止',completed:'本轮已结束',unknown:'UNKNOWN · 待核对'}[t.status]||t.status);
const occupied=t=>t.status==='running'||t.status==='responding'||t.status==='stopping'||t.status==='unknown';
const selectedTasks=()=>D.plan.mode==='single'?[D.plan.singleTask||D.plan.selected.find(id=>D.tasks.find(t=>t.id===id)?.project===D.project)].filter(Boolean):D.plan.selected;
const summaryCandidates=()=>D.tasks.filter(t=>t.project===D.project&&!t.archived&&(t.created||selectedTasks().includes(t.id)));
const projectCase=id=>id==='p1'?'c1':id==='p2'?'c2':null;
const caseGoal=id=>D.caseGoalRefs[id]||{id:'待关联',version:0,title:'待关联目标'};
const caseChoice=id=>D.choice?.caseId===id?D.choice:Object.values(D.decisionScopes||{}).find(s=>s.choice?.caseId===id)?.choice||null;
const workCase=()=>D.confirmed?D.confirmed.caseId:projectCase(D.project);
const sourceText=()=>{const ids=D.confirmed?.taskIds||[activeTask().id];return ids.length===1?`${ids[0].toUpperCase()} / 本任务分析稿 v1`:`${ids.map(x=>`${x.toUpperCase()} / 分析稿 v1`).join('；')}`;};
function notify(text){D.notice=text;render();}
function go(page){if(page==='settings'&&D.page!=='settings')D.settingsReturn={page:D.page,professional:D.professional};if(page==='chat'&&!D.tasks.some(t=>t.id===D.task&&t.project===D.project&&t.created)){D.page='plan';D.notice='本项目尚未创建任务，先在项目需求方案集中确认。';render();return;}D.page=page;D.notice='';D.professional=null;if(innerWidth<=760)D.sidebar=false;render();}
function activateTask(id){if(id===D.task)return;D.reviewScopes??={};if(D.task)D.reviewScopes[D.task]={reportVersion:D.reportVersion,reviewTab:D.reviewTab,reviews:structuredClone(D.reviews)};const r=D.reviewScopes[id]||{reportVersion:1,reviewTab:'review',reviews:{1:{reviewed:false,carried:false},2:{reviewed:false,carried:false}}};D.task=id;D.reportVersion=r.reportVersion;D.reviewTab=r.reviewTab;D.reviews=structuredClone(r.reviews);}
function selectProject(id){if(id===D.project)return;D.plans??={};D.confirmedPlans??={};D.plans[D.project]=structuredClone(D.plan);D.decisionScopes??={};D.decisionScopes[D.project]={choice:D.choice?structuredClone(D.choice):null,feedback:D.feedback?structuredClone(D.feedback):null};if(D.confirmed)D.confirmedPlans[D.project]=D.confirmed;D.project=id;D.choice=D.decisionScopes[id]?.choice||null;D.feedback=D.decisionScopes[id]?.feedback||null;const first=D.tasks.find(t=>t.project===id&&t.created&&!t.archived);activateTask(first?.id||null);D.plan=D.plans[id]||{mode:'single',selected:first?[first.id]:[],singleTask:first?.id,summary:first?.id,noCase:!projectCase(id),skills:{analysis:true,research:false,ir:false},limited:true};D.confirmed=D.confirmedPlans[id]||null;}
function openTask(id){const t=D.tasks.find(x=>x.id===id);if(!t||!t.created)return notify('尚未创建此任务。先在原项目方案中确认本轮工作。');selectProject(t.project);activateTask(id);go('chat');}
function navItem(label,page,name){return `<button class="nav-item ${D.page===page?'selected':''}" data-action="go" data-page="${page}" ${D.page===page?'aria-current="page"':''}>${icon(name)}${label}</button>`;}
function shell(){const p=activeProject(),t=activeTask();const title=({cases:'Decision Case',projects:'Project Map',goals:'战略与目标',studio:'语义与分析资产 Studio',settings:'设置',decision:'决策工作台',plan:`${p.name} / 项目需求方案`,chat:`${p.name} / ${t.name}`,help:'帮助'}[D.page]||'OptraCall');return `<div class="app" data-theme="${D.theme}"><a class="skip-link" href="#main-content">跳到主内容</a>${D.sidebar?`<aside id="sidebar" class="sidebar" aria-label="工作台导航"><div class="brand"><span class="brand-mark small" aria-hidden="true"><span></span><i></i></span><div><strong>OptraCall</strong><span>持续做出更好的决策</span></div></div><button class="new-chat" data-action="new-project">${icon('plus')}新建项目</button><nav class="primary-nav" aria-label="主导航">${navItem('战略与目标','goals','goal')}${navItem('Decision Case','cases','panel')}${navItem('Project Map','projects','folder')}${navItem('语义与分析资产','studio','assets')}</nav><div class="project-navigation"><div class="history-heading">项目空间 (${D.projects.filter(p=>!p.archived).length})</div><nav class="history project-tree" aria-label="项目空间列表"><ul>${D.projects.filter(p=>D.showArchived||!p.archived).map(p=>`<li class="project-tree-item"><div class="project-tree-row"><button class="project-disclosure" data-action="expand-project" data-id="${p.id}" aria-label="${D.expanded.includes(p.id)?'收起':'展开'}项目 ${H(p.name)}">${D.expanded.includes(p.id)?'⌄':'›'}</button><button class="project-name-button" data-action="project-detail" data-id="${p.id}">${icon('folder')}<span>${H(p.name)}</span></button><button class="project-row-action" data-action="new-task" data-id="${p.id}" aria-label="在${H(p.name)}中新建任务">＋</button><details class="project-actions-menu"><summary aria-label="项目操作 ${H(p.name)}">⋯</summary><div class="project-menu-panel">${button('重命名','rename-project','text-button',`data-id="${p.id}"`)}${button(p.archived?'恢复':'归档',p.archived?'restore-project':'archive-project','text-button',`data-id="${p.id}"`)}</div></details></div>${D.expanded.includes(p.id)?`<ul class="project-task-list">${D.tasks.filter(t=>t.project===p.id&&t.created&&(!t.archived||D.showArchived)).map(t=>`<li><button class="${t.id===D.task&&D.page==='chat'?'active':''}" data-action="open-task" data-id="${t.id}" ${t.id===D.task&&D.page==='chat'?'aria-current="page"':''}>${H(t.name)}${t.status==='running'?' · 运行中':t.archived?' · 已归档':''}</button></li>`).join('')}</ul>`:''}</li>`).join('')}</ul></nav><button class="text-button" data-action="toggle-archived">已归档项目 (${D.projects.filter(x=>x.archived).length}) ${D.showArchived?'收起':'›'}</button></div><div class="sidebar-bottom">${navItem('设置','settings','settings')}<div class="local-profile"><span class="avatar">O</span><div><strong>本地工作台</strong><span>项目与 Pi Agent</span></div></div></div></aside>`:''}<main id="main-content" class="main" tabindex="-1"><header class="topbar"><div class="topbar-context"><button class="icon-button" data-action="sidebar" aria-label="${D.sidebar?'收起':'展开'}侧栏">${icon('panel')}</button><span class="topbar-title">${H(title)}</span></div><div class="workspace-switch" role="group" aria-label="工作区切换"><button data-action="go" data-page="chat" aria-pressed="${D.page==='chat'}">分析</button><button data-action="go" data-page="decision" aria-pressed="${D.page==='decision'}">决策</button></div><div class="topbar-actions"><button class="icon-button files-toggle" data-action="files" aria-label="${D.files?'收起':'展开'}项目文件">${icon('panel')}</button><button class="help-trigger" data-action="go" data-page="help">${icon('help')}帮助</button><button class="icon-button" data-action="theme" aria-label="切换为${D.theme==='dark'?'浅色':'深色'}">${icon('sun')}</button></div></header><div class="v020-note"><span>改造 Demo v0.2 · 合成资料，仅本页内存</span><span>现有界面原样式复用；新增位置标注“本轮增量”</span><details><summary>演示说明</summary><p>不连接产品/模型，不写真实数据。原页面结构及CSS来自当前产品3ebaa01。深层不变插件只演示入口和原管理归属，不声称完成其逻辑。</p>${button('重置演示','reset','text-button')}</details></div><div class="workbench-content ${D.page==='chat'&&D.files&&D.panel==='files'?'files-visible':''} ${D.page==='chat'&&D.panel==='review'?'conclusion-visible':''}"><div class="workbench-view">${view()}</div>${D.page==='chat'?sidePanel():''}</div></main>${D.notice?`<div class="v020-toast" role="status">${H(D.notice)} ${button('关闭','clear-notice','text-button')}</div>`:''}</div>`;}
function render(){const focus=document.activeElement?.id;document.getElementById('root').innerHTML=shell();const detail=document.getElementById('v020-original-detail');if(detail){detail.showModal();detail.addEventListener('cancel',e=>{e.preventDefault();if(D.page==='cases')D.detailCase=null;else D.detailProject=null;render();});}if(focus)document.getElementById(focus)?.focus({preventScroll:true});}
function act(action,el={dataset:{}}){if((activeTask().archived||activeProject().archived)&&['send','stop','resume','finish','task-requirement','review-report','method-extract','task-case','studio-feedback'].includes(action))return notify('当前任务或项目已归档，只读。请先明确恢复原记录，再继续。');const id=el.dataset?.id,t=D.tasks.find(x=>x.id===id),p=D.projects.find(x=>x.id===id);switch(action){case'go':return go(el.dataset.page);case'clear-notice':D.notice='';break;case'reset':D=initialState();break;case'theme':D.theme=D.theme==='dark'?'light':'dark';break;case'sidebar':D.sidebar=!D.sidebar;break;case'expand-project':D.expanded=D.expanded.includes(id)?D.expanded.filter(x=>x!==id):[...D.expanded,id];break;case'project-detail':selectProject(id||D.project);D.detailProject=D.project;D.page='projects';break;case'open-task':return openTask(id);case'plan':D.page='plan';break;case'files':D.panel='files';D.files=!D.files;break;case'review':D.panel='review';D.files=false;D.page='chat';break;case'close-panel':D.panel=null;D.files=false;break;case'stop':activeTask().status='stopped';D.notice='当前任务已停止；不再启动后续自动动作或收尾提炼。已有成果保留。';break;case'resume':if(activeTask().status!=='stopped')return notify('先核对原任务、请求和稿件状态；没有自动重放。');activeTask().status='running';D.notice='按明确续接操作继续本任务，仍属运行占用，不能归档。';break;case'finish':activeTask().status='completed';D.notice='载入正常结束界面；新增节点按当前全局值和权限判断，不补跑历史。必要交付、自查和所选检查保留。';break;case'archive-task':if(!t||occupied(t))return notify('此任务仍运行、待回应或状态未知，不能归档。请先停止并核清原状态。');t.archived=true;D.notice='原任务身份、会话、来源和成果保留。归档不撤销人的决定。';break;case'restore-task':if(t){t.archived=false;D.notice='恢复原任务，未自动执行。';}break;case'archive-project':if(D.tasks.some(t=>t.project===id&&occupied(t)))return notify('项目仍有运行或未知任务，不能归档。');p.archived=true;break;case'restore-project':p.archived=false;break;case'toggle-archived':D.showArchived=!D.showArchived;break;case'case-detail':D.detailCase=id;D.page='cases';break;case'case-home':D.detailCase=null;break;case'case-mode':D.caseMode=el.dataset.mode;break;case'project-mode':D.projectMode=el.dataset.mode;break;case'project-home':D.detailProject=null;break;case'confirm-create':case'confirm-start':{const ids=selectedTasks().filter(id=>D.tasks.find(x=>x.id===id)?.project===D.project&&!D.tasks.find(x=>x.id===id)?.archived);const summary=D.plan.mode==='single'?ids[0]:D.plan.summary;if(!ids.length||!summaryCandidates().some(t=>t.id===summary))return notify('请明确有效的本项目综合责任。尚未创建且未选、已归档或其他项目任务不能承接；尚未更改任何任务。');D.confirmed={projectId:D.project,version:1,taskIds:[...ids],summary,caseId:D.plan.noCase?null:projectCase(D.project),goal:D.plan.noCase||!projectCase(D.project)?null:{...caseGoal(projectCase(D.project))},skills:{...D.plan.skills}};for(const id of new Set([...ids,summary])){const t=D.tasks.find(x=>x.id===id);t.created=true;if(action==='confirm-start')t.status='running';}activateTask(ids[0]);D.notice=action==='confirm-start'?'本次需求已确认，所选任务和综合责任已承接开始授权；无逐Task送入或再次启动。未调用模型。':'本次需求已确认并创建任务，未执行；正式RAP发布仍独立。';break;}case'carry-review':{const r=D.reviews[D.reportVersion];if(!r.reviewed)return notify('本稿未审查，不能借用另一稿意见。');if(r.carried)return notify('此准确稿件的意见已带回，复用原记录，不重复搬运。');r.carried=true;D.notice=`报告v${D.reportVersion}的准确意见已带回原任务，作者自主核实。`;break;}case'new-report':D.reportVersion=2;D.notice='修订稿v2另存，原v1和意见保留；新稿未审，不继承原PASS。';break;case'review-report':if(occupied(activeTask()))return notify('原任务仍在运行，请先完成或停止并核对后再审查。');D.reviews[D.reportVersion].reviewed=true;D.notice='载入该准确稿件的合成审查回执，不执行模型；实际意见和覆盖分开记录。';break;case'new-task':selectProject(id||D.project);if(activeProject().archived)return notify('项目已归档，只读，请先恢复项目。');return showForm('新增任务','任务名称',name=>{const id='t'+(D.tasks.length+1);D.tasks.push({id,project:D.project,name,created:true,status:'idle',archived:false,draft:''});D.notice='已创建任务，沿用项目背景，未执行。';render();});case'new-project':return showForm('新建项目','项目名称',name=>{const id='p'+(D.projects.length+1);D.projects.push({id,name,owner:'待明确',scope:'待轻量整理',next:'准备本项目需求方案',archived:false});selectProject(id);D.detailProject=id;D.page='projects';render();});case'rename-project':return showForm('重命名项目','项目名称',name=>{p.name=name;render();},p.name);default:if(typeof extraAction==='function'&&extraAction(action,el)!==false)return;return notify('此处只演示原页面及管理归属，不执行产品操作。');}render();}
function showForm(title,label,save,value=''){const dialog=document.createElement('dialog');dialog.className='v020-dialog';dialog.innerHTML=`<form><h2>${H(title)}</h2>${input('v020-dialog-input',H(label),value,'required')}<div class="v020-row">${button('取消','close-dialog')}<button class="primary-button" type="submit">保存本页演示</button></div></form>`;document.querySelector('.app').append(dialog);dialog.querySelector('[data-action="close-dialog"]').onclick=()=>{dialog.close();dialog.remove();};dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const v=dialog.querySelector('input').value.trim();if(!v)return;dialog.close();dialog.remove();save(v);};dialog.addEventListener('cancel',()=>dialog.remove());dialog.showModal();dialog.querySelector('input').focus();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;act(el.dataset.action,el);});
document.addEventListener('change',e=>{const el=e.target,k=el.dataset.change;if(!k)return;if(k==='plan-mode'){D.plan.mode=el.value;if(el.value==='single'){const first=D.tasks.find(t=>t.project===D.project&&t.created&&!t.archived)||D.tasks.find(t=>t.project===D.project&&!t.archived);D.plan.summary=first?.id;D.plan.singleTask=first?.id;D.plan.selected=first?[first.id]:[];}}else if(k==='project-filter'){D.projectFilter=el.value;D.showArchived=el.value==='all';}else if(k==='project-query')D.projectQuery=el.value;else if(k==='summary')D.plan.summary=el.value;else if(k==='no-case')D.plan.noCase=el.checked;else if(k.startsWith('selected:')){const id=k.split(':')[1];D.plan.selected=el.checked?[...new Set([...D.plan.selected,id])]:D.plan.selected.filter(x=>x!==id);}else if(k.startsWith('skill:'))D.plan.skills[k.split(':')[1]]=el.checked;else if(k.startsWith('auto:')){D.auto[k.split(':')[1]]=el.checked;D.notice='修改同一全局值，影响其他任务尚未开始的动作；未补跑或唤醒历史。';}else if(k==='auto-all'){for(const x in D.auto)D.auto[x]=el.checked;}else if(k==='report')D.reportVersion=Number(el.value);else if(k==='studio-tab')D.studioTab=el.value;else if(typeof extraChange==='function')extraChange(k,el);render();});
window.demo={get state(){return D;},act,render,initialState,summaryCandidates,sourceText,workCase,occupied};
